ediciones.reemplazo:
upsert_contact: () => {
  // phone O email: GHL acepta cualquiera de los dos como clave de upsert.
  //
  // El email hace falta para los testers de Telegram, que no tienen teléfono.
  // Fabricarles uno NO sirve: GHL valida el código de país y devuelve HTTP 400
  // "Invalid country calling code" ante un prefijo libre como +999 (medido el 14/08).
  // El teléfono sintético se sigue usando, pero sólo puertas adentro — como clave de
  // `hpf_identity` y para que W2 sepa por qué canal contestar; a GHL no llega.
  if (!args.phone && !args.email) {
    throw new Error('W0 upsert_contact: hace falta "phone" o "email"');
  }
  return { method: 'POST', path: '/contacts/upsert', body: {
    locationId: LOC, phone: args.phone, email: args.email,
    firstName: args.firstName, lastName: args.lastName, name: args.name,
    tags: args.tags, source: args.source || 'hpf-n8n' } };
},
